/**
 * Embedded default design sources for @vetwo/docs.
 *
 * These templates mirror the VeTwo design system (design/tokens.css,
 * design/base.css, design/components.css, design/README.md). docs init
 * writes them once (create-missing-only); after that the design
 * directory is user-owned and builds only read from it.
 *
 * Generated by scripts/embed-design-defaults.mjs — keep in sync with
 * the repository design/ sources.
 */

export interface DesignSourceTemplate {
  readonly path:
    | "design/tokens.css"
    | "design/base.css"
    | "design/components.css"
    | "design/README.md";
  readonly contents: string;
}

export const defaultDesignTokens = "/* ═══════════════════════════════════════════════════════════════════════\n   VeTwo Design Tokens\n   ─────────────────────────────────────────────────────────────────────\n   The single source of truth for every visual decision. Both render\n   targets (Next.js/Fumadocs site and portable static output) consume\n   this file; generated `globals.css` artifacts concatenate it verbatim.\n\n   Token vocabulary (define new ones here; never redefine elsewhere):\n     color    --vetwo-{bg, surface, surface-2, sidebar, fg, muted,\n                     border, border-strong, accent, accent-strong,\n                     accent-dim, secondary, on-accent,\n                     tone-note, tone-tip, tone-warning, tone-danger,\n                     tone-tip-bg, tone-warning-bg,\n                     tone-danger-bg, overlay, shadow, shadow-strong}\n     code     --vetwo-{code-bg, code-panel, code-border, code-fg,\n                     tok-plain, tok-comment, tok-string, tok-keyword,\n                     tok-number, tok-fn, tok-punct}\n     type     --vetwo-font-{body, heading, code},\n              --vetwo-{size-article, leading-tight, leading-body,\n                       leading-code}\n     layout   --vetwo-{header-h, measure, sidebar-w}\n     space    --vetwo-space-{1..8}\n     radius   --vetwo-radius-{small, medium, large, pill}\n     motion   --vetwo-{ease, dur-fast, dur}\n     layer    --vetwo-z-{header, sidebar}\n   ═══════════════════════════════════════════════════════════════════════ */\n\n/* ── Light scheme (default media state) ─────────────────────────────── */\n:root {\n  color-scheme: light;\n\n  /* Surfaces: cool paper with faint blue-slate tint, hairline borders. */\n  --vetwo-bg: #fafbfd;\n  --vetwo-surface: #f3f5f8;\n  --vetwo-surface-2: #eceff4;\n  --vetwo-sidebar: #f6f8fb;\n  --vetwo-overlay: rgba(10, 16, 24, 0.45);\n\n  /* Ink */\n  --vetwo-fg: #101823;\n  --vetwo-muted: #5a6a7d;\n  --vetwo-border: #e4e9ef;\n  --vetwo-border-strong: #c7d2de;\n\n  /* VeTwo accent: restrained emerald. Interactive colors only. */\n  --vetwo-accent: #059669;\n  --vetwo-accent-strong: #047857;\n  --vetwo-accent-dim: rgba(5, 150, 105, 0.11);\n  --vetwo-secondary: #0d9488;\n  --vetwo-on-accent: #ffffff;\n\n  /* Status tones (callouts) */\n  --vetwo-tone-note: #5a6a7d;\n  --vetwo-tone-tip: #059669;\n  --vetwo-tone-warning: #b45309;\n  --vetwo-tone-danger: #b91c1c;\n  --vetwo-tone-tip-bg: #effcf5;\n  --vetwo-tone-warning-bg: #fff7e6;\n  --vetwo-tone-danger-bg: #fdf0f0;\n\n  /* Elevation */\n  --vetwo-shadow: 0 1px 2px rgba(12, 20, 31, 0.06);\n  --vetwo-shadow-strong:\n    0 1px 2px rgba(12, 20, 31, 0.05), 0 6px 20px rgba(12, 20, 31, 0.1);\n\n  /* Code: a dark ink panel in both schemes; inline code keeps a light chip */\n  --vetwo-code-bg: #eef2f6;\n  --vetwo-code-panel: #0e141b;\n  --vetwo-code-border: #232d3a;\n  --vetwo-code-fg: #dbe4ee;\n  --vetwo-tok-plain: #dbe4ee;\n  --vetwo-tok-comment: #71809a;\n  --vetwo-tok-string: #9fd8b4;\n  --vetwo-tok-keyword: #7fd0e8;\n  --vetwo-tok-number: #e8c08a;\n  --vetwo-tok-fn: #c6d4f7;\n  --vetwo-tok-punct: #8695a8;\n\n  /* Typography */\n  --vetwo-font-body:\n    system-ui, -apple-system, \"Segoe UI\", Roboto, \"Helvetica Neue\", Arial,\n    \"Noto Sans\", sans-serif;\n  --vetwo-font-heading:\n    \"Inter Variable\", \"Inter\", \"SF Pro Display\", system-ui, -apple-system,\n    \"Segoe UI\", Roboto, sans-serif;\n  --vetwo-font-code:\n    \"JetBrains Mono\", ui-monospace, SFMono-Regular, Roboto Mono, Consolas,\n    \"Liberation Mono\", Menlo, monospace;\n  --vetwo-size-article: 1rem;\n  --vetwo-leading-tight: 1.25;\n  --vetwo-leading-body: 1.7;\n  --vetwo-leading-code: 1.65;\n\n  /* Layout */\n  --vetwo-header-h: 4.1rem;\n  --vetwo-measure: 48rem;\n  --vetwo-sidebar-w: 17.5rem;\n\n  /* Spacing scale */\n  --vetwo-space-1: 0.25rem;\n  --vetwo-space-2: 0.5rem;\n  --vetwo-space-3: 0.75rem;\n  --vetwo-space-4: 1rem;\n  --vetwo-space-5: 1.5rem;\n  --vetwo-space-6: 2rem;\n  --vetwo-space-7: 3rem;\n  --vetwo-space-8: 4rem;\n\n  /* Shape */\n  --vetwo-radius-small: 6px;\n  --vetwo-radius-medium: 10px;\n  --vetwo-radius-large: 14px;\n  --vetwo-radius-pill: 999px;\n\n  /* Motion */\n  --vetwo-ease: cubic-bezier(0.2, 0.8, 0.2, 1);\n  --vetwo-dur-fast: 120ms;\n  --vetwo-dur: 180ms;\n\n  /* Layers */\n  --vetwo-z-header: 20;\n  --vetwo-z-sidebar: 10;\n}\n\n/* ── Dark scheme — explicit (Fumadocs `next-themes` toggles `.dark`) ── */\n.dark {\n  color-scheme: dark;\n\n  /* Cinematic near-black with a hint of blue depth. */\n  --vetwo-bg: #070a0e;\n  --vetwo-surface: #0e1319;\n  --vetwo-surface-2: #161c24;\n  --vetwo-sidebar: #0a0e13;\n  --vetwo-overlay: rgba(2, 5, 9, 0.65);\n\n  --vetwo-fg: #e7edf4;\n  --vetwo-muted: #92a1b5;\n  --vetwo-border: #1d2733;\n  --vetwo-border-strong: #2b3849;\n\n  --vetwo-accent: #34d399;\n  --vetwo-accent-strong: #6ee7b7;\n  --vetwo-accent-dim: rgba(52, 211, 153, 0.13);\n  --vetwo-secondary: #2dd4bf;\n  --vetwo-on-accent: #06251a;\n\n  --vetwo-tone-note: #92a1b5;\n  --vetwo-tone-tip: #34d399;\n  --vetwo-tone-warning: #f0b23e;\n  --vetwo-tone-danger: #f87171;\n  --vetwo-tone-tip-bg: rgba(52, 211, 153, 0.08);\n  --vetwo-tone-warning-bg: rgba(240, 178, 62, 0.08);\n  --vetwo-tone-danger-bg: rgba(248, 113, 113, 0.08);\n\n  --vetwo-shadow: 0 1px 2px rgba(2, 5, 9, 0.55);\n  --vetwo-shadow-strong:\n    0 1px 2px rgba(2, 5, 9, 0.5), 0 8px 28px rgba(2, 5, 9, 0.6);\n\n  --vetwo-code-bg: #0e141b;\n  --vetwo-code-panel: #0d1218;\n  --vetwo-code-border: #212c39;\n  --vetwo-code-fg: #dce4ee;\n  --vetwo-tok-plain: #dce4ee;\n  --vetwo-tok-comment: #6d7d97;\n  --vetwo-tok-string: #9fd8b4;\n  --vetwo-tok-keyword: #7fd0e8;\n  --vetwo-tok-number: #e8c08a;\n  --vetwo-tok-fn: #c6d4f7;\n  --vetwo-tok-punct: #8695a8;\n}\n\n/* ── Dark scheme — OS preference (static target: no `.dark` toggling).\n       `.dark` and explicit user pinning always win. ─────────────────── */\n@media (prefers-color-scheme: dark) {\n  :root:not(.dark) {\n    color-scheme: dark;\n\n    --vetwo-bg: #070a0e;\n    --vetwo-surface: #0e1319;\n    --vetwo-surface-2: #161c24;\n    --vetwo-sidebar: #0a0e13;\n    --vetwo-overlay: rgba(2, 5, 9, 0.65);\n\n    --vetwo-fg: #e7edf4;\n    --vetwo-muted: #92a1b5;\n    --vetwo-border: #1d2733;\n    --vetwo-border-strong: #2b3849;\n\n    --vetwo-accent: #34d399;\n    --vetwo-accent-strong: #6ee7b7;\n    --vetwo-accent-dim: rgba(52, 211, 153, 0.13);\n    --vetwo-secondary: #2dd4bf;\n    --vetwo-on-accent: #06251a;\n\n    --vetwo-tone-note: #92a1b5;\n    --vetwo-tone-tip: #34d399;\n    --vetwo-tone-warning: #f0b23e;\n    --vetwo-tone-danger: #f87171;\n    --vetwo-tone-tip-bg: rgba(52, 211, 153, 0.08);\n    --vetwo-tone-warning-bg: rgba(240, 178, 62, 0.08);\n    --vetwo-tone-danger-bg: rgba(248, 113, 113, 0.08);\n\n    --vetwo-shadow: 0 1px 2px rgba(2, 5, 9, 0.55);\n    --vetwo-shadow-strong:\n      0 1px 2px rgba(2, 5, 9, 0.5), 0 8px 28px rgba(2, 5, 9, 0.6);\n\n    --vetwo-code-bg: #0e141b;\n    --vetwo-code-panel: #0d1218;\n    --vetwo-code-border: #212c39;\n    --vetwo-code-fg: #dce4ee;\n    --vetwo-tok-plain: #dce4ee;\n    --vetwo-tok-comment: #6d7d97;\n    --vetwo-tok-string: #9fd8b4;\n    --vetwo-tok-keyword: #7fd0e8;\n    --vetwo-tok-number: #e8c08a;\n    --vetwo-tok-fn: #c6d4f7;\n    --vetwo-tok-punct: #8695a8;\n  }\n}\n";

export const defaultDesignBase = "/* ═══════════════════════════════════════════════════════════════════════\n   VeTwo Base Styles\n   ─────────────────────────────────────────────────────────────────────\n   Document baseline shared by both render targets. Global element\n   defaults are intentionally scoped with `:where()` (zero specificity)\n   so component CSS and Fumadocs utilities always win.\n   ═══════════════════════════════════════════════════════════════════════ */\n\nhtml {\n  -webkit-text-size-adjust: 100%;\n  scroll-behavior: smooth;\n  /* Reserve the scrollbar lane so page layout never shifts between\n     short and long documents. */\n  scrollbar-gutter: stable;\n  text-underline-offset: 3px;\n}\n\nbody {\n  margin: 0;\n  background: var(--vetwo-bg);\n  color: var(--vetwo-fg);\n  font-family: var(--vetwo-font-body);\n  font-size: var(--vetwo-size-article);\n  line-height: var(--vetwo-leading-body);\n  -webkit-font-smoothing: antialiased;\n  text-rendering: optimizeLegibility;\n}\n\n/* Cinematic depth: one very faint accent glow at the top of the page.\n   Decoration is kept below perception threshold — only the dark scheme\n   carries it; the light scheme stays pure paper. */\nbody::before {\n  content: \"\";\n  position: fixed;\n  inset: 0;\n  z-index: -1;\n  pointer-events: none;\n}\n\n.dark body::before {\n  background: radial-gradient(\n    60rem 24rem at 70% -10%,\n    color-mix(in srgb, var(--vetwo-accent) 6%, transparent),\n    transparent 70%\n  );\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not(.dark) body::before {\n    background: radial-gradient(\n      60rem 24rem at 70% -10%,\n      color-mix(in srgb, var(--vetwo-accent) 6%, transparent),\n      transparent 70%\n    );\n  }\n}\n\nh1,\nh2,\nh3,\nh4,\nh5,\nh6 {\n  color: var(--vetwo-fg);\n  font-family: var(--vetwo-font-heading);\n  line-height: var(--vetwo-leading-tight);\n  text-wrap: balance;\n}\n\np,\nli {\n  text-wrap: pretty;\n}\n\na {\n  color: var(--vetwo-accent);\n  text-decoration: none;\n  transition: color var(--vetwo-dur-fast) var(--vetwo-ease);\n}\n\na:hover {\n  color: var(--vetwo-accent-strong);\n  text-decoration: underline;\n}\n\ncode,\npre,\nkbd {\n  font-family: var(--vetwo-font-code);\n}\n\npre {\n  overflow-x: auto;\n  max-width: 100%;\n}\n\nkbd {\n  display: inline-block;\n  padding: 0.05em 0.4em;\n  border: 1px solid var(--vetwo-border-strong);\n  border-bottom-width: 2px;\n  border-radius: calc(var(--vetwo-radius-small) - 1px);\n  background: var(--vetwo-surface);\n  color: var(--vetwo-fg);\n  font-size: 0.85em;\n  line-height: 1.4;\n}\n\nimg,\nvideo,\nsvg {\n  max-width: 100%;\n  height: auto;\n}\n\n:where(.vetwo-doc-article, .vetwo-article) {\n  font-size: var(--vetwo-size-article);\n}\n\n:where(.vetwo-doc-article h1, .vetwo-article h1) {\n  font-size: clamp(1.75rem, 4vw, 2.1rem);\n  letter-spacing: -0.02em;\n  line-height: 1.2;\n}\n\n:where(.vetwo-doc-article h2, .vetwo-article h2) {\n  font-size: 1.45rem;\n  letter-spacing: -0.015em;\n}\n\n:where(.vetwo-doc-article h3, .vetwo-article h3) {\n  font-size: 1.16rem;\n  letter-spacing: -0.01em;\n}\n\n:where(.vetwo-doc-article h4, .vetwo-article h4) {\n  font-size: 1rem;\n}\n\n:where(button, input, select, textarea, summary) {\n  font: inherit;\n}\n\n/* ── Focus: one consistent ring, accent-tinted ─────────────────────── */\n:focus {\n  outline-color: var(--vetwo-accent);\n}\n\nbutton:focus-visible,\na:focus-visible,\ninput:focus-visible,\ntextarea:focus-visible,\nselect:focus-visible,\nsummary:focus-visible,\n[tabindex]:focus-visible {\n  outline: 2px solid var(--vetwo-accent);\n  outline-offset: 2px;\n  border-radius: var(--vetwo-radius-small);\n}\n\nhtml:focus-within {\n  scroll-behavior: smooth;\n}\n\n/* ── Selection: accent-dim wash keeps text readable in both schemes ── */\n::selection {\n  background: var(--vetwo-accent-dim);\n  color: inherit;\n}\n\n/* ── Scrollbars: thin, quiet, theme-aware ──────────────────────────── */\n* {\n  scrollbar-width: thin;\n  scrollbar-color: var(--vetwo-border-strong) transparent;\n}\n\n*::-webkit-scrollbar {\n  width: 10px;\n  height: 10px;\n}\n\n*::-webkit-scrollbar-thumb {\n  background: var(--vetwo-border-strong);\n  border-radius: var(--vetwo-radius-pill);\n  border: 3px solid transparent;\n  background-clip: content-box;\n}\n\n*::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n/* ── Anchored headings account for the sticky header ───────────────── */\n:where(h1, h2, h3, h4, h5, h6)[id] {\n  scroll-margin-top: calc(var(--vetwo-header-h) + var(--vetwo-space-4));\n}\n\n/* ── Motion: honor reduced-motion first (kill switch), then ease ────── */\n@media (prefers-reduced-motion: reduce) {\n  *,\n  *::before,\n  *::after {\n    transition: none !important;\n    animation: none !important;\n    scroll-behavior: auto !important;\n  }\n}\n";

export const defaultDesignComponents = "/* ═══════════════════════════════════════════════════════════════════════\n   VeTwo Component Styles\n   ─────────────────────────────────────────────────────────────────────\n   Every `.vetwo-*` class emitted by the site renderers. One definition\n   per class; consume tokens from tokens.css only. Scoped article\n   typography uses `:where()` so it never overrides stronger rules.\n   ═══════════════════════════════════════════════════════════════════════ */\n\n/* ─── Accessibility: skip link ───────────────────────────────────────── */\n\n.vetwo-skip-link {\n  position: absolute;\n  top: -100%;\n  left: 0;\n  z-index: 100;\n  padding: var(--vetwo-space-2) var(--vetwo-space-3);\n  background: var(--vetwo-accent);\n  color: var(--vetwo-on-accent);\n  font-size: 0.85rem;\n  font-weight: 600;\n  border-radius: 0 0 var(--vetwo-radius-small) 0;\n}\n\n.vetwo-skip-link:focus {\n  top: 0;\n  color: var(--vetwo-on-accent);\n  text-decoration: none;\n}\n\n/* ─── Site header ────────────────────────────────────────────────────── */\n\n.vetwo-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: var(--vetwo-space-4);\n  padding: var(--vetwo-space-3) var(--vetwo-space-6);\n  border-bottom: 1px solid var(--vetwo-border);\n  background: color-mix(in srgb, var(--vetwo-bg) 82%, transparent);\n  backdrop-filter: blur(12px) saturate(1.3);\n  -webkit-backdrop-filter: blur(12px) saturate(1.3);\n  position: sticky;\n  top: 0;\n  z-index: var(--vetwo-z-header);\n}\n\n.vetwo-brand {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--vetwo-space-3);\n  font-weight: 700;\n  font-size: 0.95rem;\n  letter-spacing: -0.01em;\n  color: var(--vetwo-fg);\n  text-decoration: none;\n  white-space: nowrap;\n}\n\n.vetwo-brand:hover {\n  color: var(--vetwo-fg);\n  text-decoration: none;\n}\n\n.vetwo-brand svg,\n.vetwo-brand img {\n  width: 1.35rem;\n  height: 1.35rem;\n  display: block;\n  border-radius: var(--vetwo-radius-small);\n}\n\n/* One accent dot keeps the brand anchored without emoji or logos. */\n.vetwo-brand::before {\n  content: \"\";\n  width: 0.55rem;\n  height: 0.55rem;\n  flex: none;\n  border-radius: var(--vetwo-radius-pill);\n  background: var(--vetwo-accent);\n  box-shadow: 0 0 0 3px var(--vetwo-accent-dim);\n}\n\n.vetwo-header-nav {\n  display: flex;\n  align-items: center;\n  gap: var(--vetwo-space-1);\n}\n\n.vetwo-header-link {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--vetwo-space-2);\n  color: var(--vetwo-muted);\n  text-decoration: none;\n  font-size: 0.85rem;\n  font-weight: 600;\n  padding: var(--vetwo-space-2) var(--vetwo-space-3);\n  border-radius: var(--vetwo-radius-small);\n  transition:\n    color var(--vetwo-dur-fast) var(--vetwo-ease),\n    background-color var(--vetwo-dur-fast) var(--vetwo-ease);\n}\n\n.vetwo-header-link:hover {\n  color: var(--vetwo-fg);\n  background: var(--vetwo-accent-dim);\n  text-decoration: none;\n}\n\n/* ─── Layout shell (sidebar + article) ───────────────────────────────── */\n\n.vetwo-layout {\n  display: flex;\n  align-items: stretch;\n  min-height: calc(100vh - var(--vetwo-header-h));\n}\n\n.vetwo-sidebar {\n  width: var(--vetwo-sidebar-w);\n  flex: 0 0 var(--vetwo-sidebar-w);\n  background: var(--vetwo-sidebar);\n  border-right: 1px solid var(--vetwo-border);\n  padding: var(--vetwo-space-6) var(--vetwo-space-4) var(--vetwo-space-8);\n  position: sticky;\n  top: var(--vetwo-header-h);\n  align-self: flex-start;\n  max-height: calc(100vh - var(--vetwo-header-h));\n  overflow-y: auto;\n  box-sizing: border-box;\n}\n\n.vetwo-sidebar h1 {\n  font-size: 1.02rem;\n  margin: 0 0 var(--vetwo-space-1);\n  letter-spacing: -0.01em;\n}\n\n.vetwo-sidebar > p {\n  color: var(--vetwo-muted);\n  font-size: 0.8rem;\n  margin: 0 0 var(--vetwo-space-5);\n}\n\n.vetwo-nav section {\n  margin-top: var(--vetwo-space-5);\n  padding-top: var(--vetwo-space-4);\n  border-top: 1px solid var(--vetwo-border);\n}\n\n.vetwo-nav section:first-child {\n  margin-top: 0;\n  padding-top: 0;\n  border-top: 0;\n}\n\n.vetwo-nav h2,\n.vetwo-sidebar h3 {\n  font-size: 0.7rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n  color: var(--vetwo-muted);\n  margin: 0 0 var(--vetwo-space-2);\n}\n\n.vetwo-nav ul,\n.vetwo-sidebar ul {\n  list-style: none;\n  margin: 0;\n  padding: 0;\n}\n\n.vetwo-nav li,\n.vetwo-sidebar li {\n  margin: 0.125rem 0;\n}\n\n.vetwo-nav a,\n.vetwo-sidebar a {\n  position: relative;\n  color: var(--vetwo-muted);\n  text-decoration: none;\n  font-size: 0.875rem;\n  line-height: 1.45;\n  display: block;\n  padding: 0.3rem 0.65rem;\n  border-radius: var(--vetwo-radius-small);\n  transition:\n    color var(--vetwo-dur-fast) var(--vetwo-ease),\n    background-color var(--vetwo-dur-fast) var(--vetwo-ease);\n}\n\n.vetwo-nav a:hover,\n.vetwo-sidebar a:hover {\n  background: var(--vetwo-surface);\n  color: var(--vetwo-fg);\n}\n\n/* Active page: accent text plus a quiet inset bar — state is conveyed by\n   position, weight, and color together, never color alone. */\n.vetwo-nav a[aria-current=\"page\"],\n.vetwo-sidebar a[aria-current=\"page\"] {\n  background: var(--vetwo-accent-dim);\n  color: var(--vetwo-accent);\n  font-weight: 600;\n}\n\n.vetwo-nav a[aria-current=\"page\"]::before,\n.vetwo-sidebar a[aria-current=\"page\"]::before {\n  content: \"\";\n  position: absolute;\n  inset-inline-start: -0.65rem;\n  top: 0.3rem;\n  bottom: 0.3rem;\n  width: 2px;\n  border-radius: var(--vetwo-radius-pill);\n  background: var(--vetwo-accent);\n}\n\n.vetwo-main {\n  flex: 1 1 auto;\n  min-width: 0;\n  padding: 0 var(--vetwo-space-4);\n  box-sizing: border-box;\n}\n\n/* ─── Article typography ─────────────────────────────────────────────── */\n\n.vetwo-doc-article {\n  max-width: var(--vetwo-measure);\n  margin: 0 auto;\n  padding: var(--vetwo-space-6) var(--vetwo-space-5) var(--vetwo-space-8);\n}\n\n:where(.vetwo-doc-article) p {\n  margin: var(--vetwo-space-3) 0;\n}\n\n:where(.vetwo-doc-article) a:hover {\n  text-decoration: underline;\n}\n\n:where(.vetwo-doc-article) hr {\n  border: 0;\n  border-top: 1px solid var(--vetwo-border);\n  margin: var(--vetwo-space-6) 0;\n}\n\n:where(.vetwo-doc-article) ul,\n:where(.vetwo-doc-article) ol {\n  margin: var(--vetwo-space-3) 0;\n  padding-inline-start: 1.5rem;\n}\n\n:where(.vetwo-doc-article) li {\n  margin: var(--vetwo-space-1) 0;\n}\n\n:where(.vetwo-doc-article) li::marker {\n  color: var(--vetwo-accent);\n}\n\n:where(.vetwo-doc-article) blockquote {\n  margin: var(--vetwo-space-4) 0;\n  padding: var(--vetwo-space-1) 0 var(--vetwo-space-1) var(--vetwo-space-4);\n  border-inline-start: 3px solid var(--vetwo-border-strong);\n  color: var(--vetwo-muted);\n}\n\n:where(.vetwo-doc-article) figure {\n  margin: var(--vetwo-space-5) 0;\n}\n\n:where(.vetwo-doc-article) figure img {\n  border: 1px solid var(--vetwo-border);\n  border-radius: var(--vetwo-radius-medium);\n  background: var(--vetwo-surface);\n}\n\n/* Inline code: a quiet chip that reads as a token, not a button. */\n:where(.vetwo-doc-article) :not(pre) > code {\n  font-size: 0.85em;\n  background: var(--vetwo-code-bg);\n  border: 1px solid var(--vetwo-border);\n  color: var(--vetwo-fg);\n  padding: 0.1em 0.4em;\n  border-radius: var(--vetwo-radius-small);\n  overflow-wrap: anywhere;\n  font-weight: 500;\n}\n\n/* Code blocks: one shared ink panel — dark in both schemes, so code is\n   the one element that keeps its cinema regardless of theme. */\n:where(pre, .vetwo-api-signature pre, .vetwo-article pre) {\n  position: relative;\n  background: var(--vetwo-code-panel);\n  border: 1px solid var(--vetwo-code-border);\n  border-radius: var(--vetwo-radius-medium);\n  padding: var(--vetwo-space-4);\n  font-size: 0.85rem;\n  line-height: var(--vetwo-leading-code);\n  color: var(--vetwo-code-fg);\n  margin: var(--vetwo-space-4) 0;\n  tab-size: 2;\n}\n\n/* Language caption (static target emits data-language). */\npre[data-language]::after {\n  content: attr(data-language);\n  position: absolute;\n  top: 0.5rem;\n  right: 0.75rem;\n  font-family: var(--vetwo-font-code);\n  font-size: 0.65rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  color: var(--vetwo-tok-comment);\n  pointer-events: none;\n  user-select: none;\n}\n\n/* Syntax token classes (static target highlighter; shiki output in the\n   Fumadocs target carries its own inline colors). */\n:where(code) .vetwo-tok-comment {\n  color: var(--vetwo-tok-comment);\n  font-style: italic;\n}\n\n:where(code) .vetwo-tok-string {\n  color: var(--vetwo-tok-string);\n}\n\n:where(code) .vetwo-tok-keyword {\n  color: var(--vetwo-tok-keyword);\n}\n\n:where(code) .vetwo-tok-number {\n  color: var(--vetwo-tok-number);\n}\n\n:where(code) .vetwo-tok-fn {\n  color: var(--vetwo-tok-fn);\n}\n\n:where(code) .vetwo-tok-punct {\n  color: var(--vetwo-tok-punct);\n}\n\n:where(.vetwo-doc-article) h1 {\n  margin: var(--vetwo-space-1) 0 var(--vetwo-space-4);\n}\n\n:where(.vetwo-doc-article) h2 {\n  margin: var(--vetwo-space-7) 0 var(--vetwo-space-3);\n  padding-top: var(--vetwo-space-4);\n  border-top: 1px solid var(--vetwo-border);\n}\n\n:where(.vetwo-doc-article) h3 {\n  margin: var(--vetwo-space-5) 0 var(--vetwo-space-2);\n}\n\n:where(.vetwo-doc-article) h4 {\n  margin: var(--vetwo-space-4) 0 var(--vetwo-space-2);\n}\n\n.vetwo-doc-section {\n  color: var(--vetwo-muted);\n  font-size: 0.75rem;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.1em;\n  margin-bottom: var(--vetwo-space-1);\n}\n\n.vetwo-doc-description {\n  color: var(--vetwo-muted);\n  font-size: 1.1rem;\n  line-height: 1.6;\n  margin: 0 0 var(--vetwo-space-5);\n}\n\n/* ─── Breadcrumbs ────────────────────────────────────────────────────── */\n\n.vetwo-breadcrumbs {\n  font-size: 0.8rem;\n  color: var(--vetwo-muted);\n  margin-top: var(--vetwo-space-3);\n}\n\n.vetwo-breadcrumbs a {\n  color: var(--vetwo-accent);\n  text-decoration: none;\n}\n\n.vetwo-breadcrumbs a:hover {\n  color: var(--vetwo-accent-strong);\n  text-decoration: underline;\n}\n\n.vetwo-crumb-sep {\n  margin: 0 0.4em;\n  color: var(--vetwo-border-strong);\n  user-select: none;\n}\n\n.vetwo-breadcrumbs [aria-current=\"location\"] {\n  color: var(--vetwo-muted);\n  font-weight: 600;\n}\n\n/* ─── Tables ─────────────────────────────────────────────────────────── */\n\n.vetwo-table,\n.vetwo-param-table,\n:where(.vetwo-doc-article) table {\n  border-collapse: separate;\n  border-spacing: 0;\n  width: 100%;\n  margin: var(--vetwo-space-4) 0;\n  font-size: 0.92em;\n  border: 1px solid var(--vetwo-border-strong);\n  border-radius: var(--vetwo-radius-medium);\n  overflow: hidden;\n}\n\n.vetwo-table th,\n.vetwo-table td,\n.vetwo-param-table th,\n.vetwo-param-table td,\n:where(.vetwo-doc-article) th,\n:where(.vetwo-doc-article) td {\n  padding: var(--vetwo-space-2) var(--vetwo-space-3);\n  text-align: start;\n  vertical-align: top;\n  border-bottom: 1px solid var(--vetwo-border);\n}\n\n.vetwo-table th:not(:last-child),\n.vetwo-table td:not(:last-child),\n.vetwo-param-table th:not(:last-child),\n.vetwo-param-table td:not(:last-child),\n:where(.vetwo-doc-article) th:not(:last-child),\n:where(.vetwo-doc-article) td:not(:last-child) {\n  border-inline-end: 1px solid var(--vetwo-border);\n}\n\n.vetwo-table tbody tr:last-child td,\n.vetwo-param-table tbody tr:last-child td,\n:where(.vetwo-doc-article) tbody tr:last-child td {\n  border-bottom: 0;\n}\n\n.vetwo-table th,\n.vetwo-param-table th,\n:where(.vetwo-doc-article) th {\n  background: var(--vetwo-surface);\n  font-weight: 700;\n  font-size: 0.78em;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--vetwo-muted);\n}\n\n.vetwo-param-table code {\n  color: var(--vetwo-accent);\n  font-weight: 500;\n}\n\n/* ─── Callouts ───────────────────────────────────────────────────────── */\n\n.vetwo-callout {\n  display: flex;\n  gap: var(--vetwo-space-3);\n  border: 1px solid var(--vetwo-border);\n  border-inline-start: 3px solid var(--vetwo-tone-note);\n  background: var(--vetwo-surface);\n  padding: var(--vetwo-space-3) var(--vetwo-space-4);\n  border-radius: var(--vetwo-radius-small);\n  margin: var(--vetwo-space-4) 0;\n  font-size: 0.95em;\n}\n\n/* A tone dot reinforces the color of the accent bar (not color alone:\n   the strong label inside names the tone in text). */\n.vetwo-callout::before {\n  content: \"\";\n  flex: none;\n  width: 0.55rem;\n  height: 0.55rem;\n  margin-top: 0.45em;\n  border-radius: var(--vetwo-radius-pill);\n  background: var(--vetwo-tone-note);\n}\n\n.vetwo-callout-note {\n  border-inline-start-color: var(--vetwo-tone-note);\n}\n\n.vetwo-callout-note::before {\n  background: var(--vetwo-tone-note);\n}\n\n.vetwo-callout-tip {\n  border-inline-start-color: var(--vetwo-tone-tip);\n  background: var(--vetwo-tone-tip-bg);\n}\n\n.vetwo-callout-tip::before {\n  background: var(--vetwo-tone-tip);\n}\n\n.vetwo-callout-warning {\n  border-inline-start-color: var(--vetwo-tone-warning);\n  background: var(--vetwo-tone-warning-bg);\n}\n\n.vetwo-callout-warning::before {\n  background: var(--vetwo-tone-warning);\n}\n\n.vetwo-callout-deprecated {\n  border-inline-start-color: var(--vetwo-tone-danger);\n  background: var(--vetwo-tone-danger-bg);\n}\n\n.vetwo-callout-deprecated::before {\n  background: var(--vetwo-tone-danger);\n}\n\n/* ─── API reference pieces ───────────────────────────────────────────── */\n\n.vetwo-api-signature {\n  border: 1px solid var(--vetwo-border);\n  border-radius: var(--vetwo-radius-medium);\n  background: var(--vetwo-surface);\n  padding: var(--vetwo-space-4);\n  margin: var(--vetwo-space-4) 0;\n}\n\n.vetwo-api-signature pre {\n  margin: var(--vetwo-space-3) 0 0;\n  border: 0;\n  border-radius: var(--vetwo-radius-small);\n  padding: var(--vetwo-space-3);\n}\n\n.vetwo-api-badge {\n  display: inline-block;\n  font-family: var(--vetwo-font-code);\n  font-size: 0.7rem;\n  font-weight: 600;\n  text-transform: uppercase;\n  letter-spacing: 0.08em;\n  padding: 0.1em 0.5em;\n  border-radius: var(--vetwo-radius-small);\n  background: var(--vetwo-accent-dim);\n  color: var(--vetwo-accent);\n}\n\n/* ─── Search page ────────────────────────────────────────────────────── */\n\n.vetwo-search {\n  display: grid;\n  gap: var(--vetwo-space-3);\n  margin: var(--vetwo-space-4) 0 0;\n}\n\n.vetwo-search-label {\n  font-weight: 700;\n  font-size: 0.95rem;\n}\n\n.vetwo-search-input {\n  font: inherit;\n  padding: var(--vetwo-space-3) var(--vetwo-space-4);\n  border: 1px solid var(--vetwo-border);\n  border-radius: var(--vetwo-radius-medium);\n  background: var(--vetwo-surface);\n  color: var(--vetwo-fg);\n  width: 100%;\n  box-sizing: border-box;\n  transition:\n    border-color var(--vetwo-dur-fast) var(--vetwo-ease),\n    box-shadow var(--vetwo-dur-fast) var(--vetwo-ease);\n}\n\n.vetwo-search-input:focus {\n  outline: none;\n  border-color: var(--vetwo-accent);\n  box-shadow: 0 0 0 3px var(--vetwo-accent-dim);\n}\n\n.vetwo-search-hint {\n  color: var(--vetwo-muted);\n  font-size: 0.85rem;\n  margin: 0;\n}\n\n.vetwo-search-status {\n  color: var(--vetwo-muted);\n  font-size: 0.9rem;\n  min-height: 1.5em;\n}\n\n.vetwo-search-results {\n  list-style: none;\n  margin: var(--vetwo-space-4) 0 0;\n  padding: 0;\n  display: grid;\n  gap: var(--vetwo-space-3);\n}\n\n.vetwo-search-results li {\n  border: 1px solid var(--vetwo-border);\n  border-radius: var(--vetwo-radius-medium);\n  background: var(--vetwo-surface);\n  padding: var(--vetwo-space-3) var(--vetwo-space-4);\n  transition:\n    border-color var(--vetwo-dur-fast) var(--vetwo-ease),\n    box-shadow var(--vetwo-dur-fast) var(--vetwo-ease);\n}\n\n.vetwo-search-results li:hover {\n  border-color: var(--vetwo-accent);\n  box-shadow: var(--vetwo-shadow-strong);\n}\n\n.vetwo-search-results a {\n  font-weight: 700;\n}\n\n.vetwo-search-results a:hover {\n  text-decoration: underline;\n}\n\n.vetwo-search-results p {\n  margin: var(--vetwo-space-1) 0 0;\n  color: var(--vetwo-muted);\n  font-size: 0.9rem;\n}\n\n/* ─── Footer ─────────────────────────────────────────────────────────── */\n\n.vetwo-footer {\n  border-top: 1px solid var(--vetwo-border);\n  padding: var(--vetwo-space-6) var(--vetwo-space-5) var(--vetwo-space-8);\n}\n\n.vetwo-footer p {\n  max-width: var(--vetwo-measure);\n  margin: 0 auto;\n  color: var(--vetwo-muted);\n  font-size: 0.85rem;\n  text-align: center;\n}\n\n/* ═════════════════════════════════════════════════════════════════════\n   Fumadocs target extras (custom chrome wrapping the Fumadocs UI)\n   ═════════════════════════════════════════════════════════════════════ */\n\n.vetwo-article {\n  max-width: var(--vetwo-measure);\n}\n\n.vetwo-article a:hover {\n  text-decoration: underline;\n}\n\n.vetwo-graph-page {\n  max-width: 72rem;\n  margin: 0 auto;\n  padding: var(--vetwo-space-6) var(--vetwo-space-5) var(--vetwo-space-8);\n}\n\n.vetwo-graph-canvas {\n  border: 1px solid var(--vetwo-border);\n  border-radius: var(--vetwo-radius-large);\n  overflow: hidden;\n  background: var(--vetwo-surface);\n}\n\n/* ─── Responsive ─────────────────────────────────────────────────────── */\n\n@media (max-width: 920px) {\n  .vetwo-header {\n    flex-wrap: wrap;\n    padding: var(--vetwo-space-3) var(--vetwo-space-4);\n  }\n\n  .vetwo-brand {\n    white-space: normal;\n  }\n\n  .vetwo-layout {\n    flex-direction: column;\n  }\n\n  .vetwo-sidebar {\n    width: auto;\n    flex: none;\n    max-height: none;\n    position: static;\n    border-right: 0;\n    border-bottom: 1px solid var(--vetwo-border);\n    padding: var(--vetwo-space-4) var(--vetwo-space-5)\n      var(--vetwo-space-5);\n  }\n\n  .vetwo-doc-article {\n    padding: var(--vetwo-space-5) var(--vetwo-space-4)\n      var(--vetwo-space-7);\n  }\n}\n\n@media (max-width: 480px) {\n  .vetwo-header {\n    padding: var(--vetwo-space-3);\n  }\n\n  .vetwo-header-nav {\n    gap: 0;\n  }\n\n  .vetwo-doc-article {\n    padding-inline: var(--vetwo-space-3);\n  }\n}\n\n/* ─── Print: pull the article forward, drop the chrome ───────────────── */\n\n@media print {\n  .vetwo-header,\n  .vetwo-sidebar,\n  .vetwo-skip-link {\n    display: none !important;\n  }\n\n  .vetwo-layout {\n    min-height: 0;\n  }\n\n  pre,\n  :where(pre) {\n    white-space: pre-wrap;\n    overflow-wrap: anywhere;\n  }\n\n  .vetwo-doc-article,\n  .vetwo-article {\n    max-width: none;\n    padding: 0;\n  }\n}\n";

export const defaultDesignReadme = "# VeTwo Design System\n\nThis directory is the **persistent design source of truth** for all rendered\ndocumentation sites (`docs/site` Fumadocs target and `docs/static` portable\ntarget). It owns the visual identity: color, typography, spacing, motion, and\ncomponent styling.\n\n## Files\n\n| File               | Owns                                                                  |\n| ------------------ | --------------------------------------------------------------------- |\n| `tokens.css`       | Semantic design tokens (color, type, spacing, radius, motion, shadow) |\n| `base.css`         | Document baseline: resets, page defaults, focus, selection, scrollbars|\n| `components.css`   | All `.vetwo-*` component styles shared by both render targets         |\n\n## Ownership contract\n\n- These files are **user-owned design sources**. They are created once by\n  `docs init` (or on first use) and are **never regenerated or overwritten**.\n  Edit them freely; every build re-reads them from disk.\n- Emitted artifacts — `app/globals.css` in the Next.js/Fumadocs output and\n  `assets/css/globals.css` in the static output — are **generated** from these\n  sources on every build. Never edit the emitted files: the build discards\n  those changes.\n- Token overrides can also be supplied declaratively through the `theme`\n  object in `docs.config.ts`. Config values are appended after the design\n  sources, so explicit config clones the design sources in specificity and\n  order, and its values win.\n- Single source of truth: **one semantic token, one definition**. Define every\n  token in `tokens.css` only; define every class in `components.css` only.\n  Document new tokens at the top of `tokens.css` so future authors can see\n  the full vocabulary without reading the file.\n\n## Theming\n\n`tokens.css` defines a light palette on `:root` and a dark palette for\n`.dark` (Fumadocs/`next-themes` explicit toggling) and for\n`@media (prefers-color-scheme: dark)` (static target can rely on the OS\nsetting; this rule skips any document pinned by `.dark`).\n\nThe identity: cinematic near-black surfaces, restrained emerald accents used\nonly for interactive elements, status colors kept to a compact set.\n";

/** Embedded design kit: the four source files in canonical load order. */
export const DESIGN_SOURCE_TEMPLATES: readonly DesignSourceTemplate[] = [
  { path: "design/tokens.css", contents: defaultDesignTokens },
  { path: "design/base.css", contents: defaultDesignBase },
  { path: "design/components.css", contents: defaultDesignComponents },
  { path: "design/README.md", contents: defaultDesignReadme },
];
